using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;
using Zyven.Domain;
using Zyven.Application;
namespace Zyven.Infrastructure;

public sealed class BotCheckoutReferenceService(ZyvenDbContext db, TimeProvider time) { public async Task<string> Create(Guid org, Guid offer, Guid integration, long user, CancellationToken ct) { var raw = Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant(); db.Add(new BotCheckoutReference { OrganizationId = org, OfferId = offer, TelegramIntegrationId = integration, TelegramUserId = user, Hash = Hash(raw), CreatedAt = time.GetUtcNow(), ExpiresAt = time.GetUtcNow().AddDays(2) }); await db.SaveChangesAsync(ct); return raw; } public async Task Bind(string? raw, CheckoutSession checkout, CancellationToken ct) { if (string.IsNullOrWhiteSpace(raw)) return; if (raw.Length != 64) throw new OrganizationException(400, "Referência da jornada inválida."); var hash = Hash(raw); var r = await db.BotCheckoutReferences.FromSqlInterpolated($"SELECT * FROM \"BotCheckoutReferences\" WHERE \"Hash\"={hash} FOR UPDATE").SingleOrDefaultAsync(ct) ?? throw new OrganizationException(400, "Referência da jornada inválida."); if (r.ConsumedAt is not null || r.ExpiresAt <= time.GetUtcNow() || r.OrganizationId != checkout.OrganizationId || r.OfferId != checkout.OfferId) throw new OrganizationException(400, "Referência da jornada expirada."); r.ConsumedAt = time.GetUtcNow(); r.CheckoutId = checkout.Id; db.Add(new BotCheckoutBinding { CheckoutId = checkout.Id, OrganizationId = checkout.OrganizationId, TelegramIntegrationId = r.TelegramIntegrationId, TelegramUserId = r.TelegramUserId, CreatedAt = time.GetUtcNow() }); } private static string Hash(string s) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s))); }
